    for i in range(len(nums)-1,-1,-1):
            prefix[i]=prefix[i+1]+nums[i]       # found the suffix array
    leftsum=0
    while pivot<len(nums):
        if prefix[pivot+1]==leftsum:            # Checking if the left and right sums are equal
            return pivot
        leftsum+=nums[pivot]

